	if current.Name.Space != Namespace {
		err = newDeserializationError(
			fmt.Sprintf(
				"Expected only start elements in the namespace %s, "+
					"but got a start element %s in the namespace %s",
				Namespace, current.Name.Local, current.Name.Space,
			),
		)
		return
	}

	return
